WITH "g1" AS (SELECT DATE_TRUNC('MONTH', CONVERT_TIMEZONE('UTC', 'Asia/Ho_Chi_Minh', "t0"."order_date")) AS "order_date_month", "t1"."region" AS "region", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2025-12-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-09-30 17:00:00' THEN "t0"."net_amount" END) AS "revenue" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2025-12-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-09-30 17:00:00') GROUP BY DATE_TRUNC('MONTH', CONVERT_TIMEZONE('UTC', 'Asia/Ho_Chi_Minh', "t0"."order_date")), "t1"."region") SELECT "g1"."order_date_month" AS "order_date_month", "g1"."region" AS "region", "g1"."revenue" AS "revenue", LAG("g1"."revenue") OVER (PARTITION BY "g1"."region" ORDER BY "g1"."order_date_month") AS "prev_month", ("g1"."revenue" - LAG("g1"."revenue") OVER (PARTITION BY "g1"."region" ORDER BY "g1"."order_date_month")) AS "change" FROM "g1" ORDER BY "order_date_month" ASC LIMIT 1000
